with import_rows as (
 select * from jsonb_to_recordset($json$[{"reference_no":"XLSX-2026-October-income-15","entry_date":"2026-10-31","description":"October import 1 (Excel import)","debit_code":"4010","credit_code":"1010","amount":764159},{"reference_no":"XLSX-2026-October-income-16","entry_date":"2026-10-31","description":"October import 2 (Excel import)","debit_code":"1010","credit_code":"4010","amount":6000000},{"reference_no":"XLSX-2026-October-income-17","entry_date":"2026-10-31","description":"October import 3 (Excel import)","debit_code":"1010","credit_code":"4010","amount":4000000},{"reference_no":"XLSX-2026-October-expense-6","entry_date":"2026-10-01","description":"ဦးသော","debit_code":"5111","credit_code":"1010","amount":3500000},{"reference_no":"XLSX-2026-October-expense-7","entry_date":"2026-10-09","description":"Wifi","debit_code":"5112","credit_code":"1010","amount":1014758},{"reference_no":"XLSX-2026-October-expense-8","entry_date":"2026-10-01","description":"ဧည့်စားရင်း(ထွန်းထွန်းအောင်)","debit_code":"5114","credit_code":"1010","amount":30000},{"reference_no":"XLSX-2026-October-expense-9","entry_date":"2026-10-01","description":"ကားဆီ(ဦးအောင်)","debit_code":"5105","credit_code":"1010","amount":137000},{"reference_no":"XLSX-2026-October-expense-10","entry_date":"2026-10-02","description":"Alpine","debit_code":"5106","credit_code":"1010","amount":307500},{"reference_no":"XLSX-2026-October-expense-11","entry_date":"2026-10-05","description":"ဆော့ကဒ်၊ သံဖြတ်လွှ (ဒွဲအောင်)","debit_code":"5203","credit_code":"1010","amount":17500},{"reference_no":"XLSX-2026-October-expense-12","entry_date":"2026-10-07","description":"Monday Meeting","debit_code":"5101","credit_code":"1010","amount":320000},{"reference_no":"XLSX-2026-October-expense-13","entry_date":"2026-10-08","description":"ရေအေးစက် သောက်ရေသန့်","debit_code":"5106","credit_code":"1010","amount":150000},{"reference_no":"XLSX-2026-October-expense-14","entry_date":"2026-10-15","description":"ကားဆီ(ဦးအောင်)","debit_code":"5105","credit_code":"1010","amount":165000},{"reference_no":"XLSX-2026-October-expense-15","entry_date":"2026-10-15","description":"အမှိုက်အိတ်၊ ကော်ဖီ၊ သစ်သျှူး","debit_code":"5210","credit_code":"1010","amount":206800},{"reference_no":"XLSX-2026-October-expense-16","entry_date":"2026-10-17","description":"ကားဆီ(ထွန်းထွန်း)","debit_code":"5105","credit_code":"1010","amount":180000},{"reference_no":"XLSX-2026-October-expense-17","entry_date":"2026-10-20","description":"မီတာခ","debit_code":"5103","credit_code":"1010","amount":1401700},{"reference_no":"XLSX-2026-October-expense-18","entry_date":"2026-10-20","description":"ကားပြင်(ထွန်းထွန်း)","debit_code":"5203","credit_code":"1010","amount":283000},{"reference_no":"XLSX-2026-October-expense-19","entry_date":"2026-10-22","description":"ပိုးသတ်ဆေး(ထွန်းထွန်း)","debit_code":"5203","credit_code":"1010","amount":68100},{"reference_no":"XLSX-2026-October-expense-20","entry_date":"2026-10-25","description":"သောက်ရေသန့်","debit_code":"5106","credit_code":"1010","amount":28000},{"reference_no":"XLSX-2026-October-expense-21","entry_date":"2026-10-28","description":"နှစ်ထပ်ဆောင် ဘရိတ်ကာပြင်(ထွန်းထွန်း)","debit_code":"5203","credit_code":"1010","amount":261000},{"reference_no":"XLSX-2026-October-expense-22","entry_date":"2026-10-30","description":"အဲကွန်း ၉ လုံးပြင်","debit_code":"5203","credit_code":"1010","amount":545000},{"reference_no":"XLSX-2026-October-expense-23","entry_date":"2026-10-31","description":"တိုးဂိတ်ကြေး(ထွန်းထွန်း)","debit_code":"5203","credit_code":"1010","amount":5000},{"reference_no":"XLSX-2026-October-expense-24","entry_date":"2026-10-31","description":"ကားဆီ(ထွန်းထွန်း)","debit_code":"5105","credit_code":"1010","amount":142500},{"reference_no":"XLSX-2026-October-expense-25","entry_date":"2026-10-23","description":"ကားဆီဖြည့်(ထွန်း)","debit_code":"5105","credit_code":"1010","amount":137000},{"reference_no":"XLSX-2026-October-expense-26","entry_date":"2026-10-27","description":"ကားဆီ (ဦးအောင်)","debit_code":"5105","credit_code":"1010","amount":177000},{"reference_no":"XLSX-2026-October-expense-27","entry_date":"2026-10-24","description":"စီလီကွန်၊ကွန်ပယ်ရာ၊ ဆွဲကပ်( ဦးအောင်)","debit_code":"5210","credit_code":"1010","amount":101500}]$json$)
 as x(reference_no text,entry_date date,description text,debit_code text,credit_code text,amount numeric)
), configuration as (
 select (select id from public.finance_funds where code='GENERAL') as fund_id,
        '54f73659-2cc1-4ddd-822f-526c799af37f'::uuid as actor_id
), mapped as (
 select r.*, da.id as debit_account_id, ca.id as credit_account_id
 from import_rows r join public.finance_accounts da on da.code=r.debit_code join public.finance_accounts ca on ca.code=r.credit_code
), created as (
 insert into public.journal_entries(entry_date,description,reference_no,fund_id,status,created_by,submitted_by,submitted_at,approved_by,approved_at,posted_by,posted_at)
 select m.entry_date,m.description,m.reference_no,c.fund_id,'draft',c.actor_id,c.actor_id,m.entry_date::timestamptz,c.actor_id,m.entry_date::timestamptz,c.actor_id,m.entry_date::timestamptz
 from mapped m cross join configuration c where c.fund_id is not null and not exists(select 1 from public.journal_entries e where e.reference_no=m.reference_no)
 returning id,reference_no
), lines as (
 select e.id,1 as line_no,m.description,m.debit_account_id as account_id,m.amount as debit,0::numeric as credit from created e join mapped m using(reference_no)
 union all select e.id,2,m.description,m.credit_account_id,m.amount*0,m.amount from created e join mapped m using(reference_no)
), inserted_lines as (
 insert into public.journal_lines(entry_id,line_no,description,account_id,debit,credit) select id,line_no,description,account_id,debit,credit from lines returning entry_id
)
update public.journal_entries set status='posted' where id in (select entry_id from inserted_lines);
